function countGoodSubstrings(s) {
  const freq = new Array(26).fill(0);
  let repeated = 0;
  let good = 0;
  for (let right = 0; right < s.length; right++) {
    if (right >= 3) {
      const outgoing = s.charCodeAt(right - 3) - 97;
      freq[outgoing]--;
      if (freq[outgoing] === 1) {
        repeated--;
      }
    }
    const incoming = s.charCodeAt(right) - 97;
    freq[incoming]++;
    if (freq[incoming] === 2) {
      repeated++;
    }
    if (right >= 2 && repeated === 0) {
      good++;
    }
  }
  return good;
}

