function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? (rand() < 0.7 ? 100 : int(80, 100)) : int(1, 10);
  const alphabet = size === 'large' ? int(3, 26) : int(1, 5);
  const offset = int(0, 26 - alphabet);
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + offset + int(0, alphabet - 1));
  return [s];
}
